create or replace TABLE T_DIM_INTERNAL_ORGANIZATION_1 (
        INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization.',
        DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
        DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
        DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
        INT_ORG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminators for internal organizations.',
        INT_ORG_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the discriminators for internal organizations. (Description in group language, i.e. in German)',
        CURR_INT_ORG_NR VARCHAR(20) NOT NULL COMMENT 'The number by which the internal organization is currently known to business. (This number may change over time)',
        INIT_INT_ORG_NR VARCHAR(20) NOT NULL COMMENT 'The initial number for the internal organization,',
        INT_ORG_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the internal organization.',
        LEGAL_NAME VARCHAR(100) COMMENT 'In case the internal organization is an legal entity, this is its official name, as shown in the company register.',
        INT_ORG_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the lifecycle status_1 of an internal organization.',
        INT_ORG_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the lifecycle status_1 of an internal organization. (Description in group language, i.e. in German)',
        OPEN_DT DATE COMMENT 'The date when the internal organization has started its regular operation. (This date may be different from the planned opening date.)',
        PLANNED_OPEN_DT DATE COMMENT 'The expected opening date of the internal organization.',
        CLOSE_DT DATE COMMENT 'The closing date of the internal organization.',
        ISO_COUNTRY_CD VARCHAR(2) NOT NULL COMMENT 'The code according to ISO 3166 identifying the country_1, in which the internal organization is located,',
        COUNTRY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the country_1, in which the internal organization is located, (Name in group language, i.e. German)',
        CITY_NAME VARCHAR(100) COMMENT 'The name of the city where the internal organization is located.',
        DISTRICT_NAME VARCHAR(100) COMMENT 'The name of the district, in which the internal organization is located,',
        ZIP VARCHAR(15) COMMENT 'The postal code of the address_1 of the internal organization.',
        STREET_NAME VARCHAR(100) COMMENT 'The name of the street where the internal organization is located.',
        HOUSE_NR VARCHAR(100) COMMENT 'The number of the building within the street where the internal organization is located.',
        LON NUMBER(9,6) COMMENT 'The geographical longitude of the address_1 of the internal organization.',
        LAT NUMBER(9,6) COMMENT 'The geographical latitude of the address_1 of the internal organization.',
        PO_BOX_NR VARCHAR(20) COMMENT 'The post box number of the internal organization. (NULL if the internal organization does not have post box.)',
        PHONE_NR VARCHAR(100) COMMENT 'The telephone number of the internal organization.',
        FAX_NR VARCHAR(100) COMMENT 'The telefax number of the internal organization.',
        EMAIL_ADDR_TXT VARCHAR(1000) COMMENT 'An email address_1 for that internal organization.',
        REPORTING_COUNTRY_CD VARCHAR(20) NOT NULL COMMENT 'The code which identifies the reporting country_1 in which the internal organization is located.',
        REPORTING_COUNTRY_NAME VARCHAR(100) NOT NULL COMMENT 'The name the reporting country. (i.e. a country_1 definition which is different from a geographical country_1) The name in in group lanuage, i.e. in German. (Name in group language, i.e. in German)',
        IS_SALES_COMPANY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as a sales_1 company.',
        IS_DELIV_COMPANY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as a delivery company.',
        IS_COUNTRY_ORG_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as a country_1 organization.',
        IS_EXPANSION_COMPANY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as an expansion company.',
        IS_BAL_SHEET_COMPANY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as a balance sheet company.',
        IS_OWNER_COMPANY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as an owner company.',
        IS_TRUST_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the internal organization is an internal company acting as the trust (Stiftung).',
        SALES_MGR_DISTRICT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the organizational unit_1 for which the related sales_1 manager is responsible.',
        SALES_MGR_DISTRICT_NR VARCHAR(20) COMMENT 'The number which identifies the organizational unit_1 for which the related sales_1 manager is responsible.',
        SALES_MGR_DISTRICT_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related sales_1 manager district.',
        SALES_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is currently filling the position of the related sales_1 manager.',
        SALES_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the position of the related sales_1 manager.',
        SALES_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the person who is currently filling the position of the related sales_1 manager.',
        ACCT_MGR_DISTRICT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the organizational unit_1 for which the related account_1 manager is responsible.',
        ACCT_MGR_DISTRICT_NR VARCHAR(20) COMMENT 'The number which identifies the organizational unit_1 for which the related account_1 manager is responsible.',
        ACCT_MGR_DISTRICT_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related account_1 manager district.',
        ACCT_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is currently filling the position of the related account_1 manager.',
        ACCT_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the position of the related account_1 manager.',
        ACCT_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the person who is currently filling the position of the related account_1 manager.',
        SALES_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the sales_1 company (VGES) to which this internal organization is related.',
        SALES_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the sales_1 company (VGES) to which this internal organization is related.',
        SALES_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the sales_1 company to which this internal organization is related..',
        SALES_COMPANY_DIRECTOR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is the director of the related sales_1 company.',
        SALES_COMPANY_DIRECTOR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the director of the related sales_1 company.',
        SALES_COMPANY_DIRECTOR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related sales_1 company.',
        DELIV_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate key for the delivery company which is responsible for this internal organization.',
        DELIV_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the delivery company which is responsible for this internal organization.',
        DELIV_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the delivery company which is responsible for this internal organization.',
        DELIV_COMPANY_DIRECTOR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1, who is the director of the related delivery company.',
        DELIV_COMPANY_DIRECTOR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the director of the related delivery company.',
        DELIV_COMPANY_DIRECTOR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related delivery company.',
        EXPANSION_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the expansion company which is responsible for this internal organization.',
        EXPANSION_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the expansion company which is responsible for this internal organization.',
        EXPANSION_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the expansion company which is responsible for this internal organization.',
        BAL_SHEET_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the balance sheet company, which is responsible for this internal organization.',
        BAL_SHEET_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the balance sheet company, which is responsible for this internal organization.',
        BAL_SHEET_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the balance sheet company, which is responsible for this internal organization.',
        OWNER_COMPANY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the owner company, which is responsible for this internal organization.',
        OWNER_COMPANY_NR VARCHAR(20) COMMENT 'The number which identifies the owner company, which is responsible for this internal organization.',
        OWNER_COMPANY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the owner company, which is responsible for this internal organization.',
        SALES_REGION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related sales_1 region_1',
        SALES_REGION_NR VARCHAR(20) COMMENT 'The number which identifies the related sales_1 region.',
        SALES_REGION_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related sales_1 region.',
        SALES_REGION_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is currently filling the role of the manager of the related sales_1 region.',
        SALES_REGION_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the role of the manager of the related sales_1 region.',
        SALES_REGION_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related sales_1 region.',
        DELIV_REGION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related delivery region_1',
        DELIV_REGION_NR VARCHAR(20) COMMENT 'The number which identifies the related delivery region.',
        DELIV_REGION_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related delivery region.',
        DELIV_REGION_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is currently filling the role of the manager of the related delivery region.',
        DELIV_REGION_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the person who is currently filling the role of the manager of the related delivery region.',
        DELIV_REGION_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager of the related delivery region.',
        COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related country_1 organization.',
        COUNTRY_ORG_CD VARCHAR(2) COMMENT 'The code of the business country_1 for which this country_1 organization is responsible. (The business country_1 is not identical to a political country.)',
        COUNTRY_ORG_NR VARCHAR(20) COMMENT 'The number which identifies the related country_1 organization.',
        COUNTRY_ORG_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the related country_1 organization. The country_1 organization is not necessarily identical with a political country_1, (Name in group language, i.e. in German). ',
        COUNTRY_ORG_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is responsible for the related country_1 organization.',
        COUNTRY_ORG_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the manager who is responsible for the related country_1 organization.',
        COUNTRY_ORG_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager who is responsible for the related country_1 organization.',
        COUNTRY_GRP_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related organizational unit_1 which oversees the business in a group of countries.',
        COUNTRY_GRP_ORG_NR VARCHAR(20) COMMENT 'The number which identifies the related organizational unit_1 which oversees the business in a group of countries.',
        COUNTRY_GRP_ORG_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the related organizational unit_1 which oversees the business in a group of countries.',
        COUNTRY_GRP_ORG_MGR_EMP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the employee_1 who is responsible for the related group of countries.',
        COUNTRY_GRP_ORG_MGR_EMP_NR VARCHAR(20) COMMENT 'The employee_1 number of the manager who is responsible for the related group of countries.',
        COUNTRY_GRP_ORG_MGR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the manager who is responsible for the related group of countries.',
        DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
        DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
        DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
        DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
        CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code according to ISO-4217, identifying the currency which is used in this internal organization.',
        STORE_REAL_ESTATE_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the kind of buildings which are used by a store. A store may operate in a regular building (store building), in a special purpose store building or in both. ',
        STORE_REAL_ESTATE_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the kind of buildings which are used by a store. A store may operate in a regular building (store building), in a special purpose store building or in both. (Description in group language, i.e. in German)',
        INT_ORG_SHORT_NAME VARCHAR(100) COMMENT 'In case of internal companies, this column is filled with a three-letter abbreviation which identifies the internal company. E.g. LAA for Laakirchen.',
        COMP_PERIOD_START_DT DATE COMMENT 'The start date of the period in which the revenue of the store can be compared with the corresponding revenue in the previous year. When comparing the revenue, the growth that is caused purely by the increase in  the number of stores, shall be excluded. (bereinigte Steigerung) So the first year after the opening of the store needs to be excluded. The period in which revenue may be compared, starts on the first Monday after the corresponding day one year after the opening of the store, and it ends on the Sunday after the closing of the store.',
        COMP_PERIOD_END_DT DATE COMMENT 'The start date of the period in which the revenue of the store can be compared with the corresponding revenue in the previous year. When comparing the revenue, the growth that is caused purely by the increase in  the number of stores, shall be excluded. (bereinigte Steigerung) So the first year after the opening of the store needs to be excluded. The period in which revenue may be compared, starts on the first Monday after the corresponding day one year after the opening of the store, and it ends on the Sunday after the closing of the store.',
        OFFICIAL_LANG_CD VARCHAR(2) COMMENT 'Code of the official language that is used withing the organization',
        constraint PK_T_DIM_INTERNAL_ORGANIZATION primary key (INT_ORG_SID, DWH_VALID_FROM_TMSP)
) WITH ROW ACCESS POLICY #unknown_policy
COMMENT='This dimensions contains organizational units of the Schwarz Group, irrespective of their type.'
;